fn find_first_occurrence(arr: &Vec<i32>, target: i32) -> Option<usize> {
    let mut left = 0usize;
    let mut right = arr.len();

    while left < right {
        let mid = left + (right - left) / 2;
        if arr[mid] < target {
            left = mid + 1;
        } else {
            // arr[mid] >= target, so the first occurrence is at mid or before
            right = mid;
        }
    }

    // After the loop, left == right is the candidate index for first occurrence
    if left < arr.len() && arr[left] == target {
        Some(left)
    } else {
        None
    }
}